const h = (open: number, close: number): [number, number] => [open * 60, close * 60];
const week = (mf: [number, number] | null, sat: [number, number] | null, off: number[] = []): WeekHours =>
  [null, mf, mf, mf, mf, mf, sat].map((x, i) => (off.includes(i) ? null : x)) as WeekHours;

