function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export interface SeedData {
  staff: Staff[];
  chairs: Chair[];
  treatments: Treatment[];
  patients: Patient[];
  appointments: Appointment[];
  notes: Note[];
}

export function buildSeed(): SeedData {
  const rnd = mulberry32(2026);
  const pick = <T,>(arr: T[]) => arr[Math.floor(rnd() * arr.length)];
  const dentists = STAFF.filter((s) => s.title === "Dentist");

  const patients: Patient[] = NAMES.map((name, i) => ({
    id: `p-${String(i + 1).padStart(3, "0")}`,
    name,
    phone: `+355 69 555 01${String(10 + i).padStart(2, "0")}`,
    dob: `${1958 + Math.floor(rnd() * 54)}-${String(1 + Math.floor(rnd() * 12)).padStart(2, "0")}-${String(1 + Math.floor(rnd() * 28)).padStart(2, "0")}`,
    dentistId: dentists[i % dentists.length].id,
  }));

  const appointments: Appointment[] = [];
  const longAgo: LocalDT = "2000-01-01T00:00";
  let seq = 0;
  for (let d = 0; d < 6; d++) {
    const date = addDays(DEMO_WEEK_START, d);
    for (const prov of STAFF.filter((s) => s.role === "dentist")) {
      const win = prov.hours?.[(d + 1) % 7];
      if (!win) continue;
      let cur = win[0] + Math.floor(rnd() * 3) * 15;
      while (cur < win[1]) {
        if (cur >= 780 && cur < 840 && d < 5) cur = 840;
        const options = TREATMENTS.filter((t) => t.by === prov.title);
        const tr = pick(options);
        const mine = patients.filter((p) => p.dentistId === prov.id);
        const pat = prov.title === "Hygienist" || rnd() < 0.2 ? pick(patients) : pick(mine);
        const start: LocalDT = `${date}T${String(Math.floor(cur / 60)).padStart(2, "0")}:${String(cur % 60).padStart(2, "0")}`;
        const chairs = [prov.defaultChair!, ...CHAIRS.map((c) => c.id).filter((c) => c !== prov.defaultChair)];
        let placed = false;
        for (const chairId of chairs) {
          const input = { patientId: pat.id, dentistId: prov.id, chairId, treatmentId: tr.id, start };
          const v = checkAppointment(input, { provider: prov, treatment: tr, existing: appointments, now: longAgo });
          if (v.length === 0) {
            const end = addMinutes(start, tr.minutes);
            const past = toMinutes(end) <= toMinutes(DEMO_NOW);
            const r = rnd();
            let status: Appointment["status"] = past ? (r < 0.1 ? "no_show" : "completed") : "booked";
            let cancelReason: string | undefined;
            if (r > 0.93) { status = "cancelled"; cancelReason = pick(REASONS); }
            appointments.push({
              id: `a-${String(++seq).padStart(3, "0")}`,
              patientId: pat.id, dentistId: prov.id, chairId, treatmentId: tr.id,
              start, end, status, cancelReason, createdBy: pick(["s-anila", "s-gerta"]),
            });
            placed = true;
            break;
          }
        }
        cur += placed ? tr.minutes + [0, 0, 15, 15, 30, 45][Math.floor(rnd() * 6)] : 15;
        cur = Math.ceil(cur / 15) * 15;
      }
    }
  }

  const teeth = ["16", "26", "36", "46", "14", "24", "11", "21", "37", "47", "18", "28"];
  const notes: Note[] = [];
  for (const a of appointments) {
    if (a.status !== "completed" || !NOTE_TEXT[a.treatmentId] || rnd() > 0.75) continue;
    notes.push({
      id: `n-${String(notes.length + 1).padStart(3, "0")}`,
      patientId: a.patientId,
      authorId: a.dentistId,
      at: a.end,
      text: pick(NOTE_TEXT[a.treatmentId]).replace("{t}", pick(teeth)),
    });
  }
  return { staff: STAFF, chairs: CHAIRS, treatments: TREATMENTS, patients, appointments, notes };
}
